package piglatin

import "strings"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

func word(w string) string {
	if isVowel(w[0]) || strings.HasPrefix(w, "xr") || strings.HasPrefix(w, "yt") {
		return w + "ay"
	}

	// Find where the leading consonant cluster ends: the first vowel,
	// or a 'y' that is not the first letter (rule 4).
	i := 1
	for i < len(w) && !isVowel(w[i]) && w[i] != 'y' {
		i++
	}

	// If the cluster ends in 'qu', move the 'qu' along with it (rule 3).
	if i < len(w) && w[i] == 'q' && i+1 < len(w) && w[i+1] == 'u' {
		i += 2
	}

	return w[i:] + w[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

